:root {
  --bg-card: #fffdf7;
  --bg-header: #2c2416;
  --bg-active: #fdf6e3;
  --border-card: #d6c9a8;
  --border-item: #e8dfc8;
  --text-primary: #2c2416;
  --text-secondary: #7a6a4f;
  --text-header: #fffdf7;
  --text-label: #b8a882;
  --spine-red: #c0392b;
  --spine-blue: #2471a3;
  --spine-green: #1e8449;
  --spine-yellow: #d4a017;
  --spine-purple: #7d3c98;
  --status-done-bg: #d5f5e3;
  --status-done-text: #1e8449;
  --status-reading-bg: #fdebd0;
  --status-reading-text: #d35400;
  --status-queued-bg: #eaecee;
  --status-queued-text: #7f8c8d;
  --star-color: #d4a017;
  --footer-bg: #f4ede0;
}

.tracker {
  width: 520px;
  background-color: var(--bg-card);
  border: 2px solid var(--border-card);
  border-radius: 12px;
  overflow: hidden;
  font-size: 14px;
  color: var(--text-primary);
}

.tracker-header {
  background-color: var(--bg-header);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 18px;
}

.tracker-label {
  color: var(--text-header);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
}

.tracker-year {
  color: var(--text-label);
  font-size: 13px;
  font-weight: 600;
}

.book-list {
  display: flex;
  flex-direction: column;
  padding: 8px 12px;
  gap: 4px;
}

.book-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid var(--border-item);
  background-color: transparent;
}

.book-item--active {
  background-color: var(--bg-active);
  border-color: var(--spine-yellow);
}

.book-spine {
  width: 8px;
  height: 36px;
  border-radius: 2px;
  flex-shrink: 0;
}

.book-item:nth-child(1) .book-spine { background-color: var(--spine-red); }
.book-item:nth-child(2) .book-spine { background-color: var(--spine-blue); }
.book-item:nth-child(3) .book-spine { background-color: var(--spine-green); }
.book-item:nth-child(4) .book-spine { background-color: var(--spine-yellow); }
.book-item:nth-child(5) .book-spine { background-color: var(--spine-purple); }

.book-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.book-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.book-author {
  font-size: 11px;
  color: var(--text-secondary);
}

.book-status {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 20px;
  white-space: nowrap;
  flex-shrink: 0;
}

.status-done {
  background-color: var(--status-done-bg);
  color: var(--status-done-text);
}

.status-reading {
  background-color: var(--status-reading-bg);
  color: var(--status-reading-text);
}

.status-queued {
  background-color: var(--status-queued-bg);
  color: var(--status-queued-text);
}

.book-rating {
  font-size: 12px;
  color: var(--star-color);
  flex-shrink: 0;
  letter-spacing: 1px;
}

.tracker-footer {
  display: flex;
  justify-content: space-around;
  background-color: var(--footer-bg);
  padding: 10px 12px;
  border-top: 1px solid var(--border-card);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.stat-label {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}
